local function WriteGoodsLog(goodsId, num)
    xTry(function()
        num = checkNumber(num)
        local str = string.format(" ---->>>> 消耗道具Id:%s   消耗道具数量：%s", tostring(goodsId), num)
        if num > 0 then
            str = string.format(" ---->>>> 获得道具Id:%s   获得道具数量：%s", tostring(goodsId), num)
        end
        local fileName = string.format("%s_ConsumeGoods_Log.txt", os.date("%m_%d", os.time()))
        GameUtils.WriteFile(string.format("%s", fileName), str, "a+")
    end)
end

---UpdateGoodInfo
---更新道具信息
---@param goodsDojo RewardDojo
---@param playerItemId number
function GoodsUtils.__UpdateRewardInfo(goodsDojo, playerItemId)

    local goodsId = checkNumber(goodsDojo.goodsId)
    local num = checkNumber(goodsDojo.num)
    local idType = GoodsUtils.GetIdType(goodsId)

    if goodsDojo.convertGoods ~= nil and next(goodsDojo.convertGoods) ~= nil then
        idType = GoodsUtils.GetIdType(goodsDojo.convertGoods.goodsId)
        goodsId = checkNumber(goodsDojo.convertGoods.goodsId)
        num = checkNumber(goodsDojo.convertGoods.num)
    end

    local IDType = Constants.IDType
    if idType == IDType.Equipment or idType == IDType.GoodsCommission then
        ---装备
        ---@type EquipmentComponent
        local equipComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.EquipmentComponent)
        if isSet(goodsDojo, "playerEquipment") and isTable(goodsDojo.playerEquipment) and next(goodsDojo.playerEquipment) ~= nil then
            equipComp:AddEquip(goodsDojo.playerEquipment)
        else
            if not isNull(playerItemId) and checkNumber(goodsDojo.num) < 0 then
                ---移除的逻辑
                equipComp:RemoveOneEquip(playerItemId)
            end
        end
    elseif idType == IDType.EquipmentCore then
        ---装备核心
        if isSet(goodsDojo, "playerEquipmentCore") and isTable(goodsDojo.playerEquipmentCore) and next(goodsDojo.playerEquipmentCore) ~= nil then
            ---@type EquipmentComponent
            local equipComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.EquipmentComponent)
            equipComp:AddEquipCore(goodsDojo.playerEquipmentCore)
        end
    elseif idType == IDType.CharacterCard then
        local playerCard = goodsDojo.playerCard
        if isSet(goodsDojo, "playerCard") and isTable(playerCard) and next(playerCard) ~= nil then

            local id = playerCard.id
            --卡牌
            ---@type CardComponent
            local cardComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
            local dojo = cardComp:GetCardById(id)
            local isNew = dojo == nil
            if isNew then
                cardComp:AddCardDojo(playerCard)
            else
                cardComp:UpdateCardDojo(id, playerCard)
            end

            --现在获得卡牌的时候会有一个话题奖励
            local cardVo = CardConfMgr:GetInstance():GetCardByRefId(playerCard.cardId)
            if cardVo then
                -- local rewardId = checkNumber(cardVo.reward)
                -- if rewardId ~= 0 then
                --     GoodsUtils.DrawRewards({
                --         {
                --             goodsId = checkString(rewardId)
                --         }
                --     })
                -- end
                if isNew then
                    --记录新卡牌数据,为了释放大招
                    local key = "NewCards"
                    local infoString = CfUtils.GetLocalData(key)
                    local infos = {}
                    if not Tools.isNullKey(infoString) then
                        infos = table.deserialize(infoString)
                    end
                    infos[checkString(cardVo.roleId)] = true
                    CfUtils.WriteLocalData(key, table.serialize(infos))
                end
            end
        end
    elseif (idType == IDType.GoodsUsable or idType == IDType.LimitGoodsType) and checkInt(playerItemId) > 0 then
        ---@type UsableGoodComponent
        local usableGoodComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.UsableGoodComponent)
        usableGoodComp:UpdateGoodsNo({
            playerItemId = playerItemId, num = num,
            goodsId = goodsId,
            remainTime = checkNumber(goodsDojo.remainTime)
        })
        --话题道具添加
    elseif idType == IDType.PhoneTalkContent then
        local comp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PhoneComponent)
        comp:AddPhoneTalkContentId(goodsDojo.goodsId)
    elseif idType == IDType.GoodsRecipe then
        local comp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CookingComponent)
        comp:AddRecipe(goodsDojo.goodsId)
    else
        --道具更新
        GoodsUtils.__UpdateRewardNum(goodsId, num, idType, false)
    end
end

---UpdateGoodsNum
---更新道具数量
---@param goodsId number 道具id
---@param num number 更新道具数量
---@param idType Constants.IDType id类型
function GoodsUtils.__UpdateRewardNum(goodsId, num, idType)
    --添加到背包
    ---@type ECSWorldMgr
    local worldMgr = ECSWorldMgr:GetInstance()
    ---@type ECSWorld
    local world = worldMgr:GetWorld("GameWorld")
    ---@type ECSEntity
    local entity = world:GetEntity(Constants.PlayerEntityId)
    if idType == Constants.IDType.None then
        idType = GoodsUtils.GetIdType(goodsId)
    end

    --小红点本地数据更新
    local redPointCom = GameUtils.GetEntityCompByType(ECSComponentType.Constants.RedPointMgrComponent)
    redPointCom:RefreshCardSkillUpNodeWithGood(goodsId, GoodsUtils.GetThingNo(goodsId), GoodsUtils.GetThingNo(goodsId) + num)

    if idType == Constants.IDType.Currency then
        local PatrolMazeUtils = import('Game.UI.PatrolMaze.PatrolMazeUtils')
        local patrolMazeComp  = PatrolMazeUtils.GetComp()
        if goodsId == PatrolMazeUtils.GetCurrencyId() then
            local mazeAreaDojo = patrolMazeComp:GetCurrentAreaDojo()
            if mazeAreaDojo then
                mazeAreaDojo:AddMazePoint(num)
            end
        else
            --更新货币
            ---@type PlayerComponent
            local component = entity:GetComp(ECSComponentType.Constants.PlayerComponent)
            component:UpdateGoodsNo(goodsId, num)
        end
    else
        ---@type BackpackComponent
        local component = entity:GetComp(ECSComponentType.Constants.BackpackComponent)
        component:UpdateGoodsNo(goodsId, num)
    end

end

---DrawRewards
---更新奖励列表，此方法为公有方法
---@param rewards table
---@param isNotify boolean
function GoodsUtils.DrawRewards(rewards, isNotify, attachParams)
    rewards = checkTable(rewards)
    if table.count(rewards) > 0 then
        --- 插入卡牌弹窗数据 先插入 防止添加后新卡牌 不出现new 的问题
        ---@type PlayerComponent
        local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
        local cardDisplayDialogInfo = {}
        for i, v in pairs(rewards) do
            ---@type RewardDojo
            local reward = rewards[i]
            xTry(function()
                if checkNumber(reward.goodsId) == Constants.Currency.PayDiamondId
                        and checkNumber(reward.num) < 0 and isSet(reward, "productId") then
                    --是消耗一级货币的逻辑
                    xRecord.af_internal(string.format("mall_%d", checkNumber(reward.productId)), math.abs(checkNumber(reward.num)))
                end
            end)
            
            local goodsType = GoodsUtils.GetIdType(reward.goodsId)
            WriteGoodsLog(reward.goodsId, reward.num)
            if goodsType == Constants.IDType.GoodsHeadOrFrame then
                --头像头像框贴纸这类有获得时间的道具做特殊处理
                if not isNull(reward.createTime) then
                    local d = date(reward.createTime)
                    reward.createTime = d:fmt("%Y.%m.%d")
                end
                playerComponent:UpdateAvatarFramePasterGoods(reward)
            elseif goodsType == Constants.IDType.GoodsCD then
                playerComponent:UpdateCDGoods(reward)
            elseif goodsType == Constants.IDType.RoleClothes then
                local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.RoleClothesComponent)
                comp:AddRoleClothes(reward.goodsId)
            elseif goodsType == Constants.IDType.CardSkin then
                if isSet(reward,"convertGoods") and checkNumber(reward.convertGoods.goodsId) > 0 then
                    local rewardDojo = RewardDojo.New()
                    GoodsUtils.__UpdateRewardInfo(rewardDojo:Fill(reward), v.playerItemId)
                else
                    ---@type CardSkinComponent
                    local cardSkinComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardSkinComponent)
                    cardSkinComponent:AddCardSkin(reward.goodsId)
                end
            elseif goodsType == Constants.IDType.CharacterCard then
                ---@type CardComponent
                local component = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
                --- 缓存卡牌展示信息
                local goodsId = reward.goodsId
                local isExistCardData = isSet(reward, "playerCard") and isTable(reward.playerCard) and next(reward.playerCard) ~= nil
                if attachParams == nil or attachParams.isDisableCardDisplay ~= true then
                    table.insert(cardDisplayDialogInfo, { goodsId = goodsId, isNew = isExistCardData, level = isExistCardData and reward.playerCard.cardLevel or 1 })
                end

                ---@type CardSkinComponent
                local cardSkinComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardSkinComponent)
                local cardSkin = isExistCardData and checkNumber(reward.playerCard.cardSkin) or 0
                if cardSkin > 0 and not cardSkinComponent:IsHasSkin(cardSkin) then
                    cardSkinComponent:AddCardSkin(cardSkin)
                end
                --- 新增卡牌插入默认皮肤
                --- 更新背包数据
                ---@type RewardDojo
                local rewardDojo = RewardDojo.New()
                rewardDojo:Fill(reward)
                if isExistCardData and component:GetCardById(reward.playerCard.id) == nil then
                    local cardVo      = CardConfMgr:GetInstance():GetCardByRefId(goodsId)
                    local defaultSkin = cardVo.defaultSkin
                    if defaultSkin ~= cardSkin and cardSkin > 0 then
                        cardSkinComponent:AddCardSkin(defaultSkin)
                    end
                else
                    --- 因为和转换道具会共存 这里先更新转换道具 在更新卡牌数据
                    GoodsUtils.__UpdateRewardInfo(rewardDojo, v.playerItemId)
                    rewardDojo.convertGoods = nil
                end
                GoodsUtils.__UpdateRewardInfo(rewardDojo, v.playerItemId)

            elseif goodsType == Constants.IDType.GoodsIgnoreType then
                --- 不进背包的特权卡的类型
                if next(checkTable(reward.monthCard)) ~= nil then
                    ---处理月卡
                    local storeUtils = import('Game.UI.Store.StoreUtils')
                    local comp = storeUtils.GetStoreComp()
                    comp:RefreshMonthCardInfo(reward.monthCard)
                end
                if next(checkTable(reward.privilegeCards)) ~= nil then
                    -- 处理孵化月卡
                    local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
                    playerComponent:InitPrivilegeCards(reward.privilegeCards)
                end
                if next(checkTable(reward.rewards)) ~= nil then
                    ---允许在获取特权的同时获取道具，此奖励ui上不显示，直接插背包
                    GoodsUtils.DrawRewards(reward.rewards)
                end
            elseif goodsType == Constants.IDType.RestaurantRecipeGoods or goodsType == Constants.IDType.RestaurantCookingGoods or goodsType == Constants.IDType.RestaurantMaterialGoods then
                ---如果是经营相关的，食材，菜谱，料理三种类型时
                ---@type MaidCoffeePlayerComponent
                local component = GameUtils.GetEntityCompByType(ECSComponentType.Constants.MaidCoffeePlayerComponent)
                if component then
                    component:UpdateThingNo(reward.goodsId, checkTable(reward))
                end

                ---@type GuideComponent
                component = GameUtils.GetEntityCompByType(ECSComponentType.Constants.GuideComponent)
                if component then
                    component:RecordGoods(goodsType, reward.goodsId)
                end

            elseif goodsType == Constants.IDType.RenovatedGoods then
                ---如果是经营相关的家具
                ---@type MaidCoffeePlayerComponent
                local component = GameUtils.GetEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
                if component then
                    component:UpdateCafeAvatars(reward.goodsId, checkTable(reward))
                end
            elseif goodsType == Constants.IDType.OtherGoods then
                local ActionUtils = import('Game.UI.FightReady.UIMainChapter.ActionUtils')
                ActionUtils.UpdateLikabilityLvExp(v)
                local MaidCoffeeUtils = import("Game.MaidCoffee.MaidCoffeeUtils")
                MaidCoffeeUtils.UpdateCoffeeExp(v)
            elseif goodsType == Constants.IDType.GoodsCatBlindBox then
                ----猫球道具
                if isSet(reward, "catBall") and isTable(reward.catBall) then
                    ---@type CatEggComponent
                    local eggComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatEggComponent)
                    local catBall = reward.catBall
                    if catBall.convertGoods == nil then
                        ---@type CatEggDojo
                        local dojo = CatEggDojo.New()
                        dojo:FillData(reward.catBall)
                        eggComponent:DrawCatDrawReward(dojo)

                    else
                        eggComponent:UpdateConvertBackpack(catBall.convertGoods.goodsId, catBall.convertGoods.num)
                    end
                end
            elseif goodsType == Constants.IDType.GoodsCatEggs then
                ---@type CatEggComponent
                local component = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatEggComponent)
                if component == nil then
                    return
                end
                component:UpdateConvertBackpack(reward.goodsId, checkNumber(reward.num or reward.goodsNum))

            elseif goodsType == Constants.IDType.PatrolMazeGoods then
                local PatrolMazeUtils = import('Game.UI.PatrolMaze.PatrolMazeUtils')
                local patrolMazeComp  = PatrolMazeUtils.GetComp()
                local mazeAreaDojo    = patrolMazeComp:GetCurrentAreaDojo()
                if mazeAreaDojo then
                    mazeAreaDojo:AddBackpackGoods(reward)
                end

            elseif goodsType == Constants.IDType.BattleCardGameCard then
                local BattleCardGameUtils = import('Game.UI.BattleCardGame.BattleCardGameUtils')
                local battleCardGameComp  = BattleCardGameUtils.GetComp()
                local battleCardHomeDojo  = battleCardGameComp:GetHomeDojo()
                if reward.convertGoods then
                    local rewardDojo = RewardDojo.New()
                    GoodsUtils.__UpdateRewardInfo(rewardDojo:Fill(reward.convertGoods))
                else
                    reward.isNew = not battleCardHomeDojo:HasCardId(reward.goodsId)
                    battleCardHomeDojo:SaveCardId(reward.goodsId)
                end
        
            elseif goodsType ~= Constants.IDType.OtherGoods then
                local rewardDojo = RewardDojo.New()
                GoodsUtils.__UpdateRewardInfo(rewardDojo:Fill(reward), v.playerItemId)

            end
        end
        playerComponent:InsertCardDisplayDialogData(cardDisplayDialogInfo)
    end

    if checkBool(isNotify) == true then
        
        Events.Broadcast(Constants.EventNames.EveryThingChangeEventName)
    end

    ---@type QuestComponent
    local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.QuestComponent)
    comp:HandleGoodsInfo(rewards)
    -- local SDKService = import("Game.Entry.SDKService")
    -- SDKService:GetInstance():AceSDKCall("AceDataSend2")

    return rewards
end

---ConsumeGoods
---更新奖励列表，此方法为公有方法,
---与drawRewards相反的操作扣的是数量
---@param consumes table
---@param isNotify boolean
function GoodsUtils.ConsumeGoods(consumes, isNotify)
    consumes = checkTable(consumes)
    if table.count(consumes) > 0 then
        local num = 0
        for i, v in pairs(consumes) do
            v = checkTable(v)
            num = 0
            if v.num then
                num = checkNumber(v.num) * -1
                v.num = num
            elseif v.goodsNum then
                num = checkNumber(v.goodsNum) * -1
                v.goodsNum = nil
                v.num = num
            end
            --WriteGoodsLog(v.goodsId, num)
            --GoodsUtils.__UpdateRewardInfo({ goodsId = v.goodsId, num = num }, v.playerItemId)
        end
        GoodsUtils.DrawRewards(consumes,isNotify)
    end
--[[    if isNotify then  drawRewards会调用Notify
        Events.Broadcast(Constants.EventNames.EveryThingChangeEventName)
    end]]
end


---通用的获取物品数量的接口
---@param goodsId number
---@param playerGoodId number
---@return integer
function GoodsUtils.GetThingNo(goodsId, playerGoodId)
    --添加到背包
    ---@type ECSWorldMgr
    local worldMgr = ECSWorldMgr:GetInstance()
    ---@type ECSWorld
    local world = worldMgr:GetWorld("GameWorld")
    ---@type ECSEntity
    local entity = world:GetEntity(Constants.PlayerEntityId)
    local idType = GoodsUtils.GetIdType(goodsId)
    local no = 0
    if idType == Constants.IDType.Currency then
        local PatrolMazeUtils = import('Game.UI.PatrolMaze.PatrolMazeUtils')
        local patrolMazeComp  = PatrolMazeUtils.GetComp()
        --更新货币
        if goodsId == Constants.Currency.MazeCurrency then
            local MazeMgr = import('Game.Maze.MazeMgr')
            no = MazeMgr:GetInstance():GetMazeCurrencyNum()
        elseif goodsId == PatrolMazeUtils.GetCurrencyId() then
            local mazeAreaDojo = patrolMazeComp:GetCurrentAreaDojo()
            no = mazeAreaDojo and mazeAreaDojo.mazePoint or 0
        elseif goodsId == PatrolMazeUtils.GetScoreId() then
            local mazeAreaDojo = patrolMazeComp:GetCurrentAreaDojo()
            no = mazeAreaDojo and mazeAreaDojo.mazeSoure or 0
        elseif goodsId == Constants.Currency.ClubCatCarTicket then
            ---@type OverseaClubCatCarMgr
            local Mgr = import("Game.UI.Club.CatCar.OverseaClubCatCarMgr"):GetInstance()
            no =  Mgr.Server.dojo.catCarCallInfo.playerCallNum
        elseif goodsId == Constants.Currency.Fairyland then
            ---@type FairylandComponent
            local fairylandComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.FairylandComponent)
            no = fairylandComponent.dojo.hpData.hp
        else
            ---@type PlayerComponent
            local component = entity:GetComp(ECSComponentType.Constants.PlayerComponent)
            no = component:GetGoodNo(goodsId)
        end
        --elseif idType == Constants.IDType.GoodsUsable then
        --    ---@type UsableGoodComponent
        --    local component = entity:GetComp(ECSComponentType.Constants.UsableGoodComponent)
        --    if isNull(playerGoodId) then
        --        no = component:GetGoodsNo(goodsId)
        --    else
        --        no = component:GetOneGoodsNo(goodsId, playerGoodId)
        --    end
    elseif idType == Constants.IDType.RestaurantRecipeGoods or idType == Constants.IDType.RestaurantCookingGoods or idType == Constants.IDType.RestaurantMaterialGoods then
        ---如果是经营相关的，食材，菜谱，料理三种类型时
        ---@type MaidCoffeePlayerComponent
        local component = entity:GetComp(ECSComponentType.Constants.MaidCoffeePlayerComponent)
        if component then
            no = component:GetThingNo(goodsId)
        end
    elseif idType == Constants.IDType.GoodsCatEggs then
        ---@type CatEggComponent
        local component = entity:GetComp(ECSComponentType.Constants.CatEggComponent)
        if component == nil then
            return
        end
        local convertBackpack = component:GetConvertBackpack()
        local num = convertBackpack[tostring(goodsId)] or convertBackpack[checkNumber(goodsId)]
        return checkNumber(num)
    elseif idType == Constants.IDType.Equipment or idType == Constants.IDType.EquipmentCore then
        --装备的数量
        ---@type EquipmentComponent
        local equipmentComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.EquipmentComponent)
        if equipmentComponent then
            local dojo = equipmentComponent:GetEquipById(playerGoodId)
            if not isNull(dojo) then
                no = 1
            end
        end
        return no
    elseif idType == Constants.IDType.GoodsCD then
        ---cd卡
        ---@type PlayerComponent
        local playerComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PlayerComponent)
        if not isNull(playerComponent.playerDojo.ownedAlbumDt[checkNumber(goodsId)]) then
            no = 1
        end
        return no
    elseif idType == Constants.IDType.GoodsHeadOrFrame then
        ----头像或者头像框
        ---@type PlayerComponent
        local playerComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PlayerComponent)
        local headAvatarVo = PlayerInfoUtils.GetHeadAvatarVo(goodsId)
        if headAvatarVo == nil then
            return no
        end
        local type = headAvatarVo.kind--区分是头像头像框还是贴纸
        if playerComponent.playerDojo.playerOtherInfo[tostring(type)] then
            if playerComponent.playerDojo.playerOtherInfo[tostring(type)][tostring(goodsId)] then
                no = 1
            end
        end
        return no
    elseif idType == Constants.IDType.RenovatedGoods then
        local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
        local isHaveRenovate = component:IsHaveRenovated(goodsId)
        no = isHaveRenovate and 1 or 0
    elseif idType == Constants.IDType.CharacterCard then
        ---@type CardComponent
        local component = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
        no = component:GetIdByCardId(goodsId) == nil and 0 or 1
    elseif idType == Constants.IDType.CardSkin then
        ---@type CardSkinComponent
        local component = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardSkinComponent)
        return component:IsHasSkin(goodsId) and 1 or 0

    elseif idType == Constants.IDType.PatrolMazeGoods then
        local PatrolMazeUtils = import('Game.UI.PatrolMaze.PatrolMazeUtils')
        local patrolMazeComp  = PatrolMazeUtils.GetComp()
        local mazeAreaDojo    = patrolMazeComp:GetCurrentAreaDojo()
        return mazeAreaDojo and mazeAreaDojo:GetBackpackGoodsNum(goodsId) or 0
    
    elseif idType == Constants.IDType.BattleCardGameCard then
        local BattleCardGameUtils = import('Game.UI.BattleCardGame.BattleCardGameUtils')
        local battleCardGameComp  = BattleCardGameUtils.GetComp()
        local battleCardHomeDojo  = battleCardGameComp:GetHomeDojo()
        return battleCardHomeDojo:HasCardId(goodsId) and 1 or 0

    elseif idType == Constants.IDType.PatrolMazeAssist then
        local PatrolMazeUtils = import('Game.UI.PatrolMaze.PatrolMazeUtils')
        local patrolMazeComp  = PatrolMazeUtils.GetComp()
        local mazeAreaDojo    = patrolMazeComp:GetCurrentAreaDojo()
        local hasAssistCard  = mazeAreaDojo and mazeAreaDojo:HasMazeAssistCard(goodsId)
        return hasAssistCard and 1 or 0

    else
        -- 不仅仅包含背包数据，里面还会处理返回各种体力道具
        ---@type BackpackComponent
        local component = entity:GetComp(ECSComponentType.Constants.BackpackComponent)
        no = isNull(component) and 0 or component:GetGoodsNo(goodsId)
    end
    return checkNumber(no)
end

---GetConsumeGoodsText
---@param goodsId number    道具id
---@param consumeNum number 道具消耗数量
function GoodsUtils.GetConsumeGoodsText(goodsId, consumeNum, isHideX, originColor, insufficientColor)
    originColor = originColor or '#4d4d4d'
    insufficientColor = insufficientColor or '#f75757'
    local goodsNum = checkNumber(consumeNum)
    local ownNum = GoodsUtils.GetThingNo(goodsId)
    local color = ownNum >= goodsNum and originColor or insufficientColor
    local text = string.format(isHideX and "<color=%s>%s" or "<color=%s>X %s", color, goodsNum)
    return text
end

---GetGoodsText
---@param goodsId number
---@param type number  1: ownNum/consumeNum 2: consumeNum
function GoodsUtils.GetGoodsText(goodsId, consumeNum, type, insufficientColor)
    consumeNum = checkNumber(consumeNum)
    local text
    insufficientColor = insufficientColor or "#ff8383"
    if type == 1 then
        local ownNum = GoodsUtils.GetThingNo(goodsId)
        if ownNum < consumeNum then
            ownNum = FormatCurrencyNum(ownNum)
            text = string.format("<color=%s>%s</color>/%s", insufficientColor, ownNum, consumeNum)
        else
            ownNum = FormatCurrencyNum(ownNum)
            text = string.format("%s/%s", ownNum, consumeNum)
        end

    elseif type == 2 then
        text = consumeNum
    elseif type == 3 then
        local ownNum = GoodsUtils.GetThingNo(goodsId)
        if ownNum < consumeNum then
            text = string.format("<color=%s>%s", insufficientColor, consumeNum)
        else
            text = consumeNum
        end
    end

    return text
end

---CheckGoodConsume
---@param consumes table[] 消耗道具列表
---@return table, string @ rewards 消耗道具, errorTip 错误提示
function GoodsUtils.CheckGoodConsume(consumes)
    local length = #consumes
    local goodsConfMgr = GoodsConfMgr:GetInstance()
    local errorTip
    local rewards = {}
    for i = 1, length do
        local consume = consumes[i]
        local haveNo = GoodsUtils.GetThingNo(checkNumber(consume.goodsId))
        local num = consume.goodsNum or consume.num
        if haveNo < checkNumber(num) then
            ---背包不足
            local vo = goodsConfMgr:GetGoodsVoById(consume.goodsId)
            errorTip = tostring(vo.name)
            break
        end
        table.insert(rewards, { goodsId = consume.goodsId, num = -checkNumber(num) })
    end
    if not string.isEmpty(errorTip) then
        errorTip = localize("「_name_」 道具不足", { _name_ = errorTip })
    end
    return rewards, errorTip
end

---@param consumeData table @ 消耗道具数据
---@param succeedCb fun():void | nil
---@param excludeIds  table @ 互斥页面
function GoodsUtils.CheckCurrencyConsume(consumeData, succeedCb, excludeIds)
    local consumeId  = checkInt(consumeData.goodsId)
    local consumeNum = checkInt(consumeData.num)
    local goodsName  = GoodsConfMgr:GetInstance():GetGoodsNameById(consumeId)

    local _, errorTip = GoodsUtils.CheckGoodConsume({consumeData})
    if errorTip then
        ---@type ServerDifferenceMgr
        local serverDifferenceMgr = import('Game.Setting.ServerDifferenceMgr'):GetInstance()
        -- 是否开启了二级货币
        if serverDifferenceMgr:IsSecondaryCurrencyEnable() then

            -- 如果是二级货币不足，弹出货币一级货币兑换二级货币
            if consumeId == Constants.Currency.FreeDiamondId then
                local primaryId    = checkInt(checkTable(CfUtils.GetCfVo(AutoIds.IdSetting10, "BaseArgVo", 17)).num)
                local secondaryId  = checkInt(checkTable(CfUtils.GetCfVo(AutoIds.IdSetting10, "BaseArgVo", 19)).num)
                local convertRatio = checkNumber(CfUtils.GetCfVo(AutoIds.IdSetting10, "BaseArgVo", 20).num)
                local ownCount     = GoodsUtils.GetThingNo(secondaryId)
                local needCount    = consumeNum - ownCount
                local convertNum   = math.ceil(convertRatio * (needCount))
                ---@type CommonCurrencyExchangePopup.InputData
                local data = {
                    leftId         = primaryId,
                    leftNum        = convertNum,
                    rightId        = secondaryId,
                    rightNum       = needCount,
                    onConfirmClick = function()
                        local requestData = {num = convertNum}
                        GameUtils.Request(Interfaces.StoreDiamondChanges, requestData, function(request, response)
                            if checkInt(response.errCode) == 0 then
                                local consume = {goodsId = Constants.Currency.PayDiamondId, num = convertNum}
                                GoodsUtils.ConsumeGoods({consume})
                                GoodsUtils.DrawRewards(response.data.rewards)
                                if succeedCb then succeedCb() end
                            end
                        end)
                    end
                }
                serverDifferenceMgr:OpenCurrencyExchangePopup(data)
            else
                local priceData = {currency = consumeId, current = consumeNum, productName = goodsName}
                serverDifferenceMgr:WrapPrimaryCurrencyBuy(priceData, function(isSuccess)
                    if isSuccess then
                        if succeedCb then succeedCb() end
        
                    elseif consumeId ~= Constants.Currency.FreeDiamondId then
                        GameUtils.Toast(errorTip)
                    end
                end)
            end

        else
            if consumeId == Constants.Currency.FreeDiamondId then
                ---@type OverseaStoreUtils
                local OverseaStoreUtils     = import('Game.OverseaStore.OverseaStoreUtils')
                local OverseaStoreConstants = import('Game.OverseaStore.OverseaStoreConstants')
                GameUtils.SecondConfirm(localize("_name_不足, 是否前往充值？", {_name_ = goodsName}), function()
                    OverseaStoreUtils.OpenStore(OverseaStoreConstants.StoreType.TopUp, excludeIds)
                end)
            else
                GameUtils.Toast(errorTip)
            end
        end

    else
        local consumeTip = localize("确认花费_Num__Name_购买商品?", {_Num_ = consumeNum, _Name_ = goodsName})
        GameUtils.SecondConfirm(consumeTip, function()
            if succeedCb then succeedCb() end
        end)
    end
end

--- CheckGoodConsumeCondition
--- 检查道具消耗条件
---@param consumes table
---@return boolean @ 是否满足条件
function GoodsUtils.CheckGoodConsumeCondition(consumes)
    if consumes == nil or next(consumes) == nil then
        return true
    end

    for i, consume in ipairs(consumes) do
        local id = consume.goodsId or consume.id
        local haveNo = GoodsUtils.GetThingNo(checkNumber(id))
        local num = consume.goodsNum or consume.num
        if haveNo < checkNumber(num) then
            return false
        end
    end
    return true
end

---MergeUsableGoods
---配表id合并期限物品
---@param items table
function GoodsUtils.MergeUsableGoods(items)
    if not items then
        return items
    end

    local t = {}
    --将相同的配表id整合
    for k, v in pairs(items) do
        local item = t[v.goodsId]
        --如果有这个id加数量
        if item then
            item.num = checkNumber(item.num) + checkNumber(v.num)
        else
            t[v.goodsId] = v
        end
    end
    return t
end

---GetUseGoodsAddHp
---增加体力使用的期限物品   规则：不管id，遍历取时间最短
---@param goodsId number 配表id
function GoodsUtils.GetUseGoodsAddHp(targetStrength)
    targetStrength = checkNumber(targetStrength)
    local targetItems = {}
    if targetStrength <= 0 then
        return targetItems
    end

    local allItems = {}
    local ExchangeStrengthTab = CfUtils.GetCfTable(AutoIds.IdSetting302)

    ---@type UsableGoodComponent
    local usableGoodComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.UsableGoodComponent)
    local usableGoods = usableGoodComp:GetUsableGoods()
    --遍历体力兑换表拿id
    for k, v in pairs(ExchangeStrengthTab) do
        local goodsId = parse_string(v, "itemId")
        if goodsId then
            local items = usableGoods[goodsId]
            if items then
                for _, usableGood in pairs(items) do
                    table.insert(allItems, usableGood)
                end
            end
        end
    end

    --时间小的在前
    table.sort(allItems, function(a, b)
        return checkNumber(a.remainTime) < checkNumber(b.remainTime)
    end)

    --是否够
    local isEnougth = true
    for i = 1, #allItems do
        local t = {
            goodsId = allItems[i].goodsId,
            playerItemId = allItems[i].playerItemId,
            num = 0,
            isEnough = true, --显示判断用
        }
        --如果目标体力大于0 才判断
        if targetStrength > 0 then
            local needNum = CfUtils.GetItemNumByStrenth(t.goodsId, targetStrength)
            local haseNum = GoodsUtils.GetThingNo(t.goodsId, t.playerItemId)

            local exchangeStrengthVo = CfUtils.GetCfVo(AutoIds.IdSetting302, "ExchangeStrengthVo", t.goodsId)
            if haseNum >= needNum then
                t.num = needNum
                --不够
            else
                t.num = math.floor(haseNum / checkNumber(exchangeStrengthVo.itemIdCost))
            end

            targetStrength = targetStrength - t.num * (checkNumber(exchangeStrengthVo.getItemCost) / checkNumber(exchangeStrengthVo.itemIdCost))
            if i == #allItems and targetStrength > 0 then
                isEnougth = false
            end
            if checkNumber(t.num) > 0 then
                table.insert(targetItems, t)
            end
        else
            if checkNumber(t.num) > 0 then
                table.insert(targetItems, t)
            end
        end
    end

    return targetItems, targetStrength
end

function GoodsUtils.GetGoodsByType(goodsType)
    ---@type BackpackComponent
    local component = GameUtils.GetEntityCompByType(ECSComponentType.Constants.BackpackComponent)
    local GetIdType = GoodsUtils.GetIdType
    local items = {}
    --- GetAllItems
    for goodsId, value in pairs(component:GetAllItems()) do
        -- 首先检测value 是否为零 ，防止后端数据为零的时候返回
        if checkInt(value) > 0 then
            local goodType = GetIdType(goodsId)
            if goodType == goodsType then
                table.insert(items, { goodsId = goodsId, num = value })
            end
        end
    end
    return items
end
---@param goodsType number 道具类型
---是否存某种种类的道具
function GoodsUtils.ExistGoodsType(goodsType)
    local isExist = false
    ---@type BackpackComponent
    local component = GameUtils.GetEntityCompByType(ECSComponentType.Constants.BackpackComponent)
    local GetIdType = GoodsUtils.GetIdType
    local items = {}
    --- GetAllItems
    for goodsId, value in pairs(component:GetAllItems()) do
        local goodType = GetIdType(goodsId)
        if goodType == goodsType then
            if checkInt(value) > 0 then
                isExist = true
                break
            end
        end
    end
    return isExist
end

function GoodsUtils.GetGoodDictByType(goodsType, customDictHandle)
    ---@type BackpackComponent
    local component = GameUtils.GetEntityCompByType(ECSComponentType.Constants.BackpackComponent)
    local GetIdType = GoodsUtils.GetIdType
    local dict
    local checkNumber = checkNumber
    for goodsId, value in pairs(component:GetAllItems()) do
        local goodType = GetIdType(goodsId)
        if goodType == goodsType then
            if customDictHandle then
                local res = customDictHandle(dict, goodsId, value)
                if res == 1 then
                    break
                end
            else
                dict = dict or {}
                dict[checkNumber(goodsId)] = value

            end
        end
    end
    return dict
end

---GetFunctionName
---@param row TableML.TableFileRow @ 功能切割表Row
---@param goodsVo GoodsVo @ 道具vo
---@param parameterIndex integer
---@return string
function GoodsUtils.GetFunctionName(row, goodsVo, parameterIndex)
    local functionName = parse_localizeText(row, "functionName")
    if goodsVo.jumpParameter and #goodsVo.jumpParameter > 0 then
        ---存在跳转参数的情况时需要指定关卡信息
        local questId = goodsVo.jumpParameter[parameterIndex]
        if not isNull(questId) then
            local questType = GoodsUtils.GetIdType(questId, Constants.IDArea.Quests)
            if questType == Constants.IDType.QuestMain or questType == Constants.IDType.QuestCoinsCopy or questType == Constants.IDType.QuestExpCopy or questType == Constants.IDType.QuestUpStarCopy then
                ---副本
                ---@type QuestDailyVo
                local vo = QuestConfMgr:GetInstance():GetQuestVoById(questId)
                if isTable(vo) then
                    functionName = string.format('%s(%s)', functionName, vo.label)
                end

            end
        end
    end
    return functionName
end

---CheckConsumeData
---@param consumeData_ table 消耗道具 { {goodsId: number, num: number } }
---@param orderInLayer_ number | nil @ 指定 ui canvas 排序层级
---@return boolean 是否满足条件
function GoodsUtils.CheckConsumeDataCondition(consumeData_, orderInLayer_)
    local t = {}
    for i, consume in ipairs(consumeData_) do
        local goodsId = consume.goodsId
        local ownNum = GoodsUtils.GetThingNo(goodsId)
        local goodsNum = consume.goodsNum or consume.num
        if ownNum < checkNumber(goodsNum) then
            table.insert(t, { goodsId = goodsId, num = goodsNum, gainNum = goodsNum - ownNum })
        end

    end

    local res = next(t) == nil
    if not res then
        GoodsUtils.ShowCommonLackMaterialDialog(t,orderInLayer_)
    end

    return res
end

---ShowCommonLackMaterialDialog
---@param lackGoods_ table 不足的道具 { {goodsId: number, num: number } }
---@param orderInLayer_ number | nil @ 指定 ui canvas 排序层级
function GoodsUtils.ShowCommonLackMaterialDialog(lackGoods_, orderInLayer_)
    local UIModule = CS.Engine.UI.UIModule
    UIModule.OpenDialog({ id = Constants.UITypeIds.CommonLackMaterialDialog, parameters = { lackGoods = lackGoods_, orderInLayer = orderInLayer_ } })
end

---SpiltGold
---将金币从消耗道具列表中分离
---@param goods table {goodsId = x, goodsNum = x}
function GoodsUtils.SpiltGold(goods)
    local t, goodsNum = {}, 0
    local checkNumber = checkNumber
    local GoldId = Constants.Currency.GoldId
    for i, v in ipairs(goods) do
        if checkNumber(v.goodsId) == GoldId then
            goodsNum = checkNumber(v.goodsNum or v.num)
        else
            table.insert(t, v)
        end
    end
    return t, goodsNum
end

