---@param goodsType integer @ Tips: 千万不要这样取type传入，一定要读取 GoodsVo.type
---@return BackpackVo
function GoodsUtils.GetBasicPacketByGoodsType(goodsType)
    goodsType = checkInt(goodsType)
    local aPacket = nil
    local packets = GoodsUtils.GetBasicPackets()
    for _, packet in pairs(packets) do
        for _, itemType in pairs(packet.itemType) do
            if checkInt(itemType) == goodsType then
                aPacket = packet
                break
            end
        end
        if aPacket then
            break
        end
    end
    return aPacket
end

---IsPacketFilled
---是否背包存在已满的情况，不能再进行打关等情况
function GoodsUtils.IsPacketFilled()
    local packets = GoodsUtils.GetBasicPackets()
    local isFilled = false
    ---@type BackpackComponent
    local backpackComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.BackpackComponent)
    local equipComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.EquipmentComponent)

    for _, v in pairs(packets) do
        ---@type BackpackVo
        local packet = GoodsUtils.GetBasicPacket(v.refId)
        if packet.initialNum > 0 then
            for _, itemType in pairs(packet.itemType) do
                itemType = checkNumber(itemType)
                if itemType == Constants.IDType.Equipment then
                    local count = 0
                    local equips = equipComp:GetAllEquips()
                    for _, _v in pairs(equips) do
                        if checkNumber(_v.playerCardId) <= 0 then
                            count = count + 1
                        end
                    end

                    local limitCount = backpackComponent:GetPacketLimitByPacketId(packet.id)
                    if count > limitCount then
                        return true, packet
                    end
                else
                    if backpackComponent:IsGoodsTypePacketFull(itemType, backpackComponent:GetPacketLimitByPacketId(packet.id)) then
                        isFilled = true
                        return isFilled, packet
                    end
                end
            end
        end
    end

    return isFilled
end

--- 指定类型的背包是否已满
---@param packetId Constants.BackpackTypeId
---@return boolean
function GoodsUtils.IsPacketFilledById(packetId)
    ---@type BackpackComponent
    local backpackComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.BackpackComponent)
    local isFilled = false
    ---@type BackpackVo
    local packet = GoodsUtils.GetBasicPacket(packetId)
    if packet.initialNum > 0 then
        if packetId == Constants.BackpackTypeId.EQUIP then
            local packLimit = backpackComponent:GetPacketLimitByPacketId(packetId)
            local packOwned = backpackComponent:GetGoodsNumByPacketId(packetId)
            return packOwned >= packLimit
        else
            for i, itemType in pairs(packet.itemType) do
                if backpackComponent:IsGoodsTypePacketFull(itemType, backpackComponent:GetPacketLimitByPacketId(packet.id)) then
                    isFilled = true
                    return isFilled
                end
            end
        end
    end
    return isFilled
end
