--- 根据提供的道具判断对应的背包是否已满
---@param goods any
function GoodsUtils.IsGoodsPacketFull(goods)
    local goodsTypeList = {}
    for _, good in ipairs(goods) do
        local goodsId   = checkInt(good.id or good.goodsId)
        local goodsVo   = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
        local goodsType = checkInt(goodsVo.type)
        table.insert(goodsTypeList, tostring(goodsType))
    end
    for _, goodsType in ipairs(goodsTypeList) do
        local backpackVo = GoodsUtils.GetBasicPacketByGoodsType(goodsType)
        local isFilled   = backpackVo and GoodsUtils.IsPacketFilledById(backpackVo.id) or false
        if isFilled then
            return true, backpackVo
        end
    end
    return false
end

---是否为卡牌相关类型
function GoodsUtils.IsCardType(id)
    if not id then return false end

    local type = GoodsUtils.GetIdType(id)
    if type == Constants.IDType.CharacterCard or
            type == Constants.IDType.CardSkin or
            type == Constants.IDType.RoleCardCustomize then
        return true
    else
        return false
    end
end

--- 获取上标的描述和status
---@param type number Constants.RewardSourceType
function GoodsUtils.GetRewardSourceDesc(type)
    local desc = ""

    local sourceType = Constants.RewardSourceType
    if type == sourceType.None then
    elseif type == sourceType.Certain then
        desc = localize("必定掉落")
    elseif type == sourceType.Probabilistic then
        desc = localize("概率掉落")
    elseif type == sourceType.FirstPass then
        desc = localize("首通奖励")
    elseif type == sourceType.ThreeStars then
        desc = localize("三星奖励")
    elseif type == sourceType.Final then
        desc = localize("最终奖励")
    elseif type == sourceType.Captain then
        desc = localize("队长奖励")
    elseif type == sourceType.Fixed then
        desc = localize("固定奖励")
    elseif type == sourceType.Sweep then
        desc = localize("扫荡奖励")
    elseif type == sourceType.Realtime then
        desc = localize("实时掉落")
    end
    return desc
end


